import{_ as t,o as l,c as e,a4 as r}from"./chunks/framework.BYKJayo6.js";const b=JSON.parse('{"title":"DLC03・デルタの夜明け","description":"Anno 117 DLC03「デルタの夜明け（Dawn of the Delta）」の情報ページ。エジプト地方アイギュプト・灌漑システム・新祭神ソベクなどを解説（2026年11月5日リリース予定）。","frontmatter":{"title":"DLC03・デルタの夜明け","description":"Anno 117 DLC03「デルタの夜明け（Dawn of the Delta）」の情報ページ。エジプト地方アイギュプト・灌漑システム・新祭神ソベクなどを解説（2026年11月5日リリース予定）。"},"headers":[],"relativePath":"guide/dlc03-dawn-of-delta.md","filePath":"guide/dlc03-dawn-of-delta.md"}'),i={name:"guide/dlc03-dawn-of-delta.md"};function o(n,a,d,h,s,u){return l(),e("div",null,[...a[0]||(a[0]=[r('<h1 id="dlc03・デルタの夜明け" tabindex="-1">DLC03・デルタの夜明け <a class="header-anchor" href="#dlc03・デルタの夜明け" aria-label="Permalink to &quot;DLC03・デルタの夜明け&quot;">​</a></h1><blockquote><p>出典: <a href="https://www.anno-union.com/gamescom-recap-dawn-of-the-delta-and-echoes-of-kassandra/" target="_blank" rel="noreferrer">Anno Union公式ブログ「Gamescom recap: Dawn of the Delta and Echoes of Kassandra」</a>（2026年9月3日）、<a href="https://www.anno-union.com/roadmap-for-2026/" target="_blank" rel="noreferrer">「Roadmap for 2026」</a>（2026年9月30日更新）、<a href="https://www.anno-union.com/devblog-arriving-in-aegyptus/" target="_blank" rel="noreferrer">「Arriving in Aegyptus」</a>（デブログ第1回、2026年10月15日。地形とゾーンの説明はこちらを優先）、<a href="https://www.anno-union.com/devblog-population-floods-and-the-power-of-knowledge/" target="_blank" rel="noreferrer">「Population, Floods and the power of knowledge」</a>（デブログ第2回、2026年10月22日。住民層・生産チェーン・洪水と灌漑）、<a href="https://www.anno-union.com/devblog-of-unsatiable-deities-and-warmongering-rivals/" target="_blank" rel="noreferrer">「Of unsatiable deities and warmongering rivals」</a>（デブログ第3回、2026年10月29日。新祭神・ライバル・ピラミッド）。 本ページの内容は今後変更される可能性があります。</p></blockquote><blockquote><p>このページは作成中です。確定情報が増え次第、随時更新します。</p></blockquote><h2 id="概要" tabindex="-1">概要 <a class="header-anchor" href="#概要" aria-label="Permalink to &quot;概要&quot;">​</a></h2><ul><li>舞台は帝国南東部の<strong>アイギュプト</strong>（ナイル川デルタ地方）。</li><li>新規ゲーム開始時の地域として選択できるほか、既存セーブでもDLC有効化により探索可能になります。</li><li><strong>灌漑システム</strong>・新祭神・独自の軍事ユニットが導入されます。</li><li><strong>2026年11月5日</strong>、無料アップデート3.0と同時リリースが予定されています。</li></ul><h2 id="地形・建築エリア" tabindex="-1">地形・建築エリア <a class="header-anchor" href="#地形・建築エリア" aria-label="Permalink to &quot;地形・建築エリア&quot;">​</a></h2><p>土地は3つのゾーンに分かれます。</p><table tabindex="0"><thead><tr><th>ゾーン</th><th>特徴</th></tr></thead><tbody><tr><td>アリッドゾーン</td><td>内陸にあり、農業には向かないが、都市の建設に適している</td></tr><tr><td>ファームランド</td><td>海岸沿いにあり、農業と港の建設に使う</td></tr><tr><td>氾濫原</td><td>川沿いにあり、洪水の影響を受ける。泥のおかげで建物の生産量が増える。葦・泥などの産地</td></tr></tbody></table><h2 id="住民層" tabindex="-1">住民層 <a class="header-anchor" href="#住民層" aria-label="Permalink to &quot;住民層&quot;">​</a></h2><p>初期層は<strong>スレッシャー</strong>（脱穀者。農業の伝統を担う階層）です。基本の需要を満たすと、次の2路線から選びます。名前は仮の訳です。</p><table tabindex="0"><thead><tr><th>路線</th><th>第2階層</th><th>第3階層</th></tr></thead><tbody><tr><td>エジプト（伝統）</td><td>ポッター（陶工）</td><td>チャンター（詠唱者・女司祭）</td></tr><tr><td>ギリシャ・ローマ</td><td>スクライブ（書記）</td><td>ジムナシアーク（体育場長）</td></tr></tbody></table><p>各層の需要は<a href="/wiki/population.html#アイギュプト住民層">住民層のページ</a>にまとめています。</p><h2 id="公共施設" tabindex="-1">公共施設 <a class="header-anchor" href="#公共施設" aria-label="Permalink to &quot;公共施設&quot;">​</a></h2><ul><li><strong>エジプト路線</strong>: 薬局（薬草園つき。健康と知識）、聖域または神殿（現地の神々）、岩窟墓（上流階級向け。山のスロットが必要）、天文台（信仰+5、知識+3）。</li><li><strong>ローマ路線</strong>: 劇場、浴場（水道橋が必要）、図書館（油ランプに注意）。</li></ul><h2 id="新しい商品・生産チェーン" tabindex="-1">新しい商品・生産チェーン <a class="header-anchor" href="#新しい商品・生産チェーン" aria-label="Permalink to &quot;新しい商品・生産チェーン&quot;">​</a></h2><ul><li><strong>タリスマン</strong>（ポッター向け）: 銅と砂から青い染料を作り、現地の粘土で作ったタリスマンを染めます。</li><li><strong>書写セット</strong>（スクライブ向け）: パピルス（葦が必要）と、現地の鉱物から作る顔料で作ります。</li><li><strong>シストラム</strong>（チャンター向け）: 現地の銅と錫から作った青銅に、氾濫原で採れるビーズを組み合わせます。</li><li>パン・ビール・石鹸などは、ラティウム・アルビオン・アイギュプトのどこで作るか、輸入か現地生産かを選べます。</li><li>需要品の一覧は<a href="/wiki/population.html#アイギュプト住民層">住民層のページ</a>を参照。</li></ul><h2 id="穀倉" tabindex="-1">穀倉 <a class="header-anchor" href="#穀倉" aria-label="Permalink to &quot;穀倉&quot;">​</a></h2><ul><li>範囲内の農場の生産性が+15%、人口ボーナスが+1。農産物を1基あたり100t追加で保管できます。</li><li>スキルでアップグレードできます。</li><li>保管上限を超えるとあふれ、ネズミが出ることがあります。超過が多く、穀倉のレベルが低いほど起きやすく、島の健康度が下がって総督の決定を誘発します。</li><li>対策は、穀倉のアップグレードと、猫好きの専門家「Catfriend Cattulus」の雇用です。</li></ul><h2 id="洪水と灌漑" tabindex="-1">洪水と灌漑 <a class="header-anchor" href="#洪水と灌漑" aria-label="Permalink to &quot;洪水と灌漑&quot;">​</a></h2><h3 id="季節の影響" tabindex="-1">季節の影響 <a class="header-anchor" href="#季節の影響" aria-label="Permalink to &quot;季節の影響&quot;">​</a></h3><ul><li><strong>氾濫期</strong>: 氾濫原の建物の生産性が75%下がります。州全体で、全建物の健康が-2、防火が+2になります。</li><li><strong>収穫期</strong>: 氾濫原の生産建物の生産量が、サイクルごとに+1tになります。</li></ul><h3 id="灌漑の方式" tabindex="-1">灌漑の方式 <a class="header-anchor" href="#灌漑の方式" aria-label="Permalink to &quot;灌漑の方式&quot;">​</a></h3><ul><li><strong>ベイスン方式</strong>: 海岸に貯水池（ベイスン）を建て、内陸へ運河を伸ばします。運河の両側8フィールドが農地になり、乾燥地帯を農業用地に変えられます。その分、都市の建設スペースは減ります。農業専用の島を作る手もあります。</li><li><strong>水路サンプ</strong>: 運河に接続し、道路もつなぐと、範囲内で健康+1、防火+3になります。</li><li><strong>ノリア方式</strong>（第3階層で解放）: 川の水をノーリア水車でくみ上げ、水道橋で内陸へ送ります。貯水槽（シスターン）は浴場の水源になるほか、周囲の円形範囲も農地にします。</li></ul><h2 id="スキルツリー" tabindex="-1">スキルツリー <a class="header-anchor" href="#スキルツリー" aria-label="Permalink to &quot;スキルツリー&quot;">​</a></h2><p>アイギュプトには、専用のスキルツリーが用意されます。スキルで次のことができるようになります。</p><ul><li>氾濫原でより多様な作物を育て、生産ボーナスを得る。</li><li>灌漑設備を強化して、生産建物の水使用量を減らす。長い運河も建設できるようになる。</li><li>アイギュプトで石鹸などを生産できるようにする。</li><li>現地の新しい神々を発見する。</li></ul><h2 id="宗教" tabindex="-1">宗教 <a class="header-anchor" href="#宗教" aria-label="Permalink to &quot;宗教&quot;">​</a></h2><p>新祭神が3柱導入されます。名前は仮の訳です。</p><ul><li><strong>ソベク</strong>：「デルタ川の神」。研究なしで使えます。チーズソーセージ・詰めガチョウ・サンガ牛などの食料生産が増え、灌漑用水とボーナス人口も増えます。世界的な信仰ボーナスで鳩小屋が解放され、プランテーションに付けると生産性が上がります。</li><li><strong>イシス＝バステト</strong>：研究ツリーで発見が必要です。ラベンダー・香水・ナツメヤシの生産が増え、住民の商品消費量は減ります。世界的な信仰で祭りの持続時間が延び、大型の猫の神殿が解放されます（影響範囲が広く、人口・収入・名声が上がる）。</li><li><strong>トート＝トリスメギストス</strong>：研究ツリーで発見が必要です。ガラス・ワイン・書字板・書写セットなどの生産が増えます。島の収入と名声は知識レベルに連動します。世界的に広がると、図書館の範囲内の全建物の生産が増えます。</li></ul><p>エジプトの神を信仰すると、聖域・神殿の外観がエジプト風（猫やワニの聖域など）になります。</p><h2 id="ピラミッド" tabindex="-1">ピラミッド <a class="header-anchor" href="#ピラミッド" aria-label="Permalink to &quot;ピラミッド&quot;">​</a></h2><p>島ではなく、州全体のプロジェクトです。ナウクラティスの近くにあり、修復すると州全体にボーナスが付きます。</p><ul><li>修復の各段階で、タイル・花崗岩・大理石・チュニック・労働者の食料・輸送用のヒトコブラクダなどを、ピラミッド用の波止場に納めます。</li><li>段階ごとの効果は、全島での帝国の土地税の低下と名声の上昇です。ライバルがいると、先に必要量を納めた総督ほど強い効果を得られます。</li><li>完成時にピリミディオン（頂石）を載せると、州全体の名声ボーナスと、英雄スペシャリストの出現確率の一時的な上昇が得られます。新しい英雄スペシャリストは3人です。</li><li>儀式を定期的に行うと、効果の持続時間を延ばせます。</li><li>修復したピラミッドは、第3階層（チャンター・ジムナシアーク）の需要になり、幸福と名声を与えます。</li></ul><h2 id="キャラクター" tabindex="-1">キャラクター <a class="header-anchor" href="#キャラクター" aria-label="Permalink to &quot;キャラクター&quot;">​</a></h2><p>メインストーリーは殺人ミステリーで、ナウクラティスで遺体が見つかるところから始まります。ストーリーを飛ばして、島の経営に専念することもできます。</p><table tabindex="0"><thead><tr><th>名前</th><th>役割</th></tr></thead><tbody><tr><td>エピストラテゴス・ヘロン（Epistrategos Heron）</td><td>ナウクラティスの皇帝代理人。軍事力はほぼ無く、仲介役・商人</td></tr><tr><td>ヴァレリア（Valeria）</td><td>川沿いの小さな港を拠点に、交易帝国を広げる</td></tr><tr><td>カンディス（Kandis）</td><td>ファラオの谷を拠点とする略奪者。身代金を要求し、払わないと攻撃してくる。倒すには、港の破壊と谷への軍の派遣が必要</td></tr><tr><td>デキムス・ナウクラティウス・ネルウァ（Decimus Naukratius Nerva）</td><td>「エジプトの暴君」。ライバル総督として追加できる。キャンペーン主人公の父</td></tr></tbody></table><p>日本語名は仮の訳です。</p><h2 id="新軍事ユニット・船舶" tabindex="-1">新軍事ユニット・船舶 <a class="header-anchor" href="#新軍事ユニット・船舶" aria-label="Permalink to &quot;新軍事ユニット・船舶&quot;">​</a></h2><ul><li><strong>エリート・クシテ弓兵</strong>（Kumatic Archers）：通常の遠距離ユニットより攻撃力・命中率・射程が高い。採用費と維持費も高い。</li><li><strong>ドロメダリイ騎兵</strong>（ラクダ騎兵）：敵の騎兵・歩兵ユニットの士気を低下させる効果を持ちます。騎馬ユニットに強くやや安価ですが、足の速い馬には追いつけません。</li><li>2体とも、スキルツリーで先に研究する必要があります。スキルの1つで、ラティウム以外でもレギオナリウス（軍団兵）を徴募できるようになります。</li><li>アイギュプト専用の造船所で、改造できない船を2種建造できます。 <ul><li>スキフ（Skiff、エポルコン）：最初から建造可能。非武装で、貨物スロットは3。</li><li>ガレー（Galley、アバ）：スキルで解放。貨物スロットは5。軍事型は複数のアーチャーを載せられます。</li></ul></li><li>ローマ船は外洋向けで頑丈ですが、浅い河口のデルタでは扱いにくく、アイギュプト船は浅瀬に強く速いです。川の輸送は現地の船、地域間の輸送はローマ船に積み替える使い分けが勧められています。海岸近くの貨物ハブも有用とされています。</li></ul><h2 id="その他" tabindex="-1">その他 <a class="header-anchor" href="#その他" aria-label="Permalink to &quot;その他&quot;">​</a></h2><ul><li>他地域との交易により、独自の経済戦略を構築できます。</li></ul><h2 id="無料アップデート3-0の内容" tabindex="-1">無料アップデート3.0の内容 <a class="header-anchor" href="#無料アップデート3-0の内容" aria-label="Permalink to &quot;無料アップデート3.0の内容&quot;">​</a></h2><p>DLC03と同じ<strong>2026年11月5日</strong>に配信予定です。</p><ul><li>統計メニューにアイテム一覧と倉庫一覧を追加</li><li><strong>スタンプ機能</strong>：建物の配置をテンプレートとして保存し、再利用できます</li><li>属性・外交などのバランス調整</li><li>栄誉の殿堂のコンテンツ追加</li></ul><p>詳しいパッチノートは、リリースが近づいてから公開される予定です。</p><h2 id="未発表の要素" tabindex="-1">未発表の要素 <a class="header-anchor" href="#未発表の要素" aria-label="Permalink to &quot;未発表の要素&quot;">​</a></h2><p>以下は、まだ発表されていません。</p><ul><li>ピラミッドの各段階の必要量と効果量、儀式の内容</li><li>需要品の数量、建物・スキルツリーの詳細</li><li>数値バランス（生産量・信仰要求量など）</li></ul><h2 id="関連データ" tabindex="-1">関連データ <a class="header-anchor" href="#関連データ" aria-label="Permalink to &quot;関連データ&quot;">​</a></h2><ul><li><a href="/wiki/">データベース一覧</a> — 現在公開中のゲームデータ</li></ul>',50)])])}const g=t(i,[["render",o]]);export{b as __pageData,g as default};
